import{_ as t,a0 as o,w as d,s as c,I as a,x as n,a1 as l,A as p,ao as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"32 位支持：使用 GCC 交叉編譯 | LCTT x X-CMD","titleTemplate":false,"description":"32 位支持：使用 GCC 交叉編譯 | LCTT (201907) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"32 位支持：使用 GCC 交叉編譯 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"32 位支持：使用 GCC 交叉編譯 | LCTT (201907) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201907/20190710 32-bit life support- Cross-compiling with GCC","title":"32 位支持：使用 GCC 交叉編譯","tag":"201907","desc":""},"relativePath":"201907/20190710 32-bit life support- Cross-compiling with GCC.md","filePath":"[post].md"}'),r={name:"201907/20190710 32-bit life support- Cross-compiling with GCC.md"};function u(g,s,b,h,k,C){const i=o("Link");return d(),c("div",null,[s[29]||(s[29]=a("h1",{id:"_32-位支持-使用-gcc-交叉編譯",tabindex:"-1"},[n("32 位支持：使用 GCC 交叉編譯 "),a("a",{class:"header-anchor",href:"#_32-位支持-使用-gcc-交叉編譯","aria-label":"Permalink to “32 位支持：使用 GCC 交叉編譯”"},"​")],-1)),s[30]||(s[30]=a("blockquote",null,[a("p",null,"使用 GCC 在單一的構建機器上來為不同的 CPU 架構交叉編譯二進制文件。")],-1)),s[31]||(s[31]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/201907/19/054242nwhludz9tm2lwd8t.jpg",alt:""})],-1)),a("p",null,[s[1]||(s[1]=n("如果你是一個開發者，要創建二進制軟件包，像一個 RPM、DEB、Flatpak 或 Snap 軟件包，你不得不為各種不同的目標平台編譯代碼。典型的編譯目標包括 32 位和 64 位的 x86 和 ARM。你可以在不同的物理或虛擬機器上完成你的構建，但這需要你為何幾個系統。作為代替，你可以使用 GNU 編譯器集合 (",-1)),l(i,{href:"https://gcc.gnu.org/"},{default:p(()=>[...s[0]||(s[0]=[n("GCC",-1)])]),_:1}),s[2]||(s[2]=n(") 來交叉編譯，在單一的構建機器上為幾個不同的 CPU 架構產生二進制文件。",-1))]),s[32]||(s[32]=e(`<p>假設你有一個想要交叉編譯的簡單的擲骰子游戲。在大多數系統上，以 C 語言來編寫這個相對簡單，出於給添加現實的複雜性的目的，我以 C++ 語言寫這個示例，所以程序依賴於一些不在 C 語言中東西 (具體來説就是 <code>iostream</code>)。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#include &lt;iostream&gt;</span></span>
<span class="line"><span>#include &lt;cstdlib&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>using namespace std;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>void lose (int c); </span></span>
<span class="line"><span>void win (int c); </span></span>
<span class="line"><span>void draw (); </span></span>
<span class="line"><span></span></span>
<span class="line"><span>int main() { </span></span>
<span class="line"><span>  int i; </span></span>
<span class="line"><span>    do { </span></span>
<span class="line"><span>      cout &lt;&lt; &quot;Pick a number between 1 and 20: \\n&quot;; </span></span>
<span class="line"><span>      cin &gt;&gt; i; </span></span>
<span class="line"><span>      int c = rand ( ) % 21; </span></span>
<span class="line"><span>      if (i &gt; 20) lose (c); </span></span>
<span class="line"><span>      else if (i &lt; c ) lose (c); </span></span>
<span class="line"><span>      else if (i &gt; c ) win (c); </span></span>
<span class="line"><span>      else draw (); </span></span>
<span class="line"><span>      } </span></span>
<span class="line"><span>      while (1==1); </span></span>
<span class="line"><span>      }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>void lose (int c ) </span></span>
<span class="line"><span>  { </span></span>
<span class="line"><span>    cout &lt;&lt; &quot;You lose! Computer rolled &quot; &lt;&lt; c &lt;&lt; &quot;\\n&quot;; </span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>void win (int c ) </span></span>
<span class="line"><span>  { </span></span>
<span class="line"><span>    cout &lt;&lt; &quot;You win!! Computer rolled &quot; &lt;&lt; c &lt;&lt; &quot;\\n&quot;; </span></span>
<span class="line"><span>   }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>void draw ( ) </span></span>
<span class="line"><span>   { </span></span>
<span class="line"><span>     cout &lt;&lt; &quot;What are the chances. You tied. Try again, I dare you! \\n&quot;;</span></span>
<span class="line"><span>   }</span></span></code></pre></div><p>在你的系統上使用 <code>g++</code> 命令編譯它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ g++ dice.cpp -o dice</span></span></code></pre></div><p>然後，運行它來確認其工作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ./dice</span></span>
<span class="line"><span>Pick a number between 1 and 20:</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>你可以使用 <code>file</code> 命令來查看你剛剛生產的二進制文件的類型：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ file ./dice</span></span>
<span class="line"><span>dice: ELF 64-bit LSB executable, x86-64, version 1 (SYSV), dynamically</span></span>
<span class="line"><span>linked (uses shared libs), for GNU/Linux 5.1.15, not stripped</span></span></code></pre></div><p>同樣重要，使用 <code>ldd</code> 命令來查看它鏈接哪些庫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ldd dice</span></span>
<span class="line"><span>linux-vdso.so.1 =&amp;gt; (0x00007ffe0d1dc000)</span></span>
<span class="line"><span>libstdc++.so.6 =&amp;gt; /usr/lib/x86_64-linux-gnu/libstdc++.so.6</span></span>
<span class="line"><span>(0x00007fce8410e000)</span></span>
<span class="line"><span>libc.so.6 =&amp;gt; /lib/x86_64-linux-gnu/libc.so.6</span></span>
<span class="line"><span>(0x00007fce83d4f000)</span></span>
<span class="line"><span>libm.so.6 =&amp;gt; /lib/x86_64-linux-gnu/libm.so.6</span></span>
<span class="line"><span>(0x00007fce83a52000)</span></span>
<span class="line"><span>/lib64/ld-linux-x86-64.so.2 (0x00007fce84449000)</span></span>
<span class="line"><span>libgcc_s.so.1 =&amp;gt; /lib/x86_64-linux-gnu/libgcc_s.so.1</span></span>
<span class="line"><span>(0x00007fce8383c000)</span></span></code></pre></div><p>從這些測試中，你已經確認了兩件事：你剛剛運行的二進制文件是 64 位的，並且它鏈接的是 64 位庫。</p><p>這意味着，為實現 32 位交叉編譯，你必需告訴 <code>g++</code> 來：</p><ol><li>產生一個 32 位二進制文件</li><li>鏈接 32 位庫，而不是 64 位庫</li></ol><h3 id="設置你的開發環境" tabindex="-1">設置你的開發環境 <a class="header-anchor" href="#設置你的開發環境" aria-label="Permalink to “設置你的開發環境”">​</a></h3>`,14)),a("p",null,[s[4]||(s[4]=n("為編譯成 32 位二進制，你需要在你的系統上安裝 32 位的庫和頭文件。如果你運行一個純 64 位系統，那麼，你沒有 32 位的庫或頭文件，並且需要安裝一個基礎集合。最起碼，你需要 C 和 C++ 庫（",-1)),s[5]||(s[5]=a("code",null,"glibc",-1)),s[6]||(s[6]=n(" 和 ",-1)),s[7]||(s[7]=a("code",null,"libstdc++",-1)),s[8]||(s[8]=n("）以及 GCC 庫（",-1)),s[9]||(s[9]=a("code",null,"libgcc",-1)),s[10]||(s[10]=n("）的 32 位版本。這些軟件包的名稱可能在每個發行版中不同。在 Slackware 系統上，一個純 64 位的帶有 32 位兼容的發行版，可以從 ",-1)),l(i,{href:"http://www.slackware.com/~alien/multilib/"},{default:p(()=>[...s[3]||(s[3]=[n("Alien BOB",-1)])]),_:1}),s[11]||(s[11]=n(" 提供的 ",-1)),s[12]||(s[12]=a("code",null,"multilib",-1)),s[13]||(s[13]=n(" 軟件包中獲得。在 Fedora、CentOS 和 RHEL 系統上：",-1))]),s[33]||(s[33]=e(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ yum install libstdc++-*.i686</span></span>
<span class="line"><span>$ yum install glibc-*.i686</span></span>
<span class="line"><span>$ yum install libgcc.i686</span></span></code></pre></div><p>不管你正在使用什麼系統，你同樣必須安裝一些你工程使用的 32 位庫。例如，如果你在你的工程中包含 <code>yaml-cpp</code>，那麼，在編譯工程前，你必需安裝 <code>yaml-cpp</code> 的 32 位版本，或者，在很多系統上，安裝 <code>yaml-cpp</code> 的開發軟件包（例如，在 Fedora 系統上的 <code>yaml-cpp-devel</code>）。</p><p>一旦這些處理好了，編譯是相當簡單的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ g++ -m32 dice.cpp -o dice32 -L /usr/lib -march=i686</span></span></code></pre></div><p><code>-m32</code> 標誌告訴 GCC 以 32 位模式編譯。<code>-march=i686</code> 選項進一步定義來使用哪種最優化類型（參考 <code>info gcc</code> 瞭解選項列表）。<code>-L</code> 標誌設置你希望 GCC 來鏈接的庫的路徑。對於 32 位來説通常是 <code>/usr/lib</code>，不過，這依賴於你的系統是如何設置的，它可以是 <code>/usr/lib32</code>，甚至 <code>/opt/usr/lib</code>，或者任何你知道存放你的 32 位庫的地方。</p><p>在代碼編譯後，查看你的構建的證據：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ file ./dice32</span></span>
<span class="line"><span>dice: ELF 32-bit LSB executable, Intel 80386, version 1 (SYSV),</span></span>
<span class="line"><span>dynamically linked (uses shared libs) [...]</span></span></code></pre></div><p>接着，當然， <code>ldd ./dice32</code> 也會指向你的 32 位庫。</p><h3 id="不同的架構" tabindex="-1">不同的架構 <a class="header-anchor" href="#不同的架構" aria-label="Permalink to “不同的架構”">​</a></h3><p>在 64 位相同的處理器家族上允許 GCC 做出很多關於如何編譯代碼的假設來編譯 32 位軟件。如果你需要為完全不同的處理器編譯，你必需安裝適當的交叉構建實用程序。安裝哪種實用程序取決於你正在編譯的東西。這個過程比為相同的 CPU 家族編譯更復雜一點。</p><p>當你為相同處理器家族交叉編譯時，你可以期待找到與 32 位庫集的相同的 64 位庫集，因為你的 Linux 發行版是同時維護這二者的。當為一個完全不同的架構編譯時，你可能不得不窮追你的代碼所需要的庫。你需要的版本可能不在你的發行版的存儲庫中，因為你的發行版可能不為你的目標系統提供軟件包，或者它不在容易到達的位置提供所有的軟件包。如果你正在編譯的代碼是你寫的，那麼你可能非常清楚它的依賴關係是什麼，並清楚在哪裏找到它們。如果代碼是你下載的，並需要編譯，那麼你可能不熟悉它的要求。在這種情況下，研究正確編譯代碼需要什麼（它們通常被列在 <code>README</code> 或 <code>INSTALL</code> 文件中，當然也出現在源文件代碼自身之中），然後收集需要的組件。</p><p>例如，如果你需要為 ARM 編譯 C 代碼，你必須首先在 Fedora 或 RHEL 上安裝 <code>gcc-arm-linux-gnu</code>（32 位）或 <code>gcc-aarch64-linux-gnu</code>（64 位）；或者，在 Ubuntu 上安裝 <code>arm-linux-gnueabi-gcc</code> 和 <code>binutils-arm-linux-gnueabi</code>。這提供你需要用來構建（至少）一個簡單的 C 程序的命令和庫。此外，你需要你的代碼使用的任何庫。你可以在慣常的位置（大多數系統上在 <code>/usr/include</code>）放置頭文件，或者，你可以放置它們在一個你選擇的目錄，並使用 <code>-I</code> 選項將 GCC 指向它。</p><p>當編譯時，不使用標準的 <code>gcc</code> 或 <code>g++</code> 命令。作為代替，使用你安裝的 GCC 實用程序。例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ arm-linux-gnu-g++ dice.cpp \\</span></span>
<span class="line"><span>  -I/home/seth/src/crossbuild/arm/cpp \\</span></span>
<span class="line"><span>  -o armdice.bin</span></span></code></pre></div><p>驗證你構建的內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ file armdice.bin</span></span>
<span class="line"><span>armdice.bin: ELF 32-bit LSB executable, ARM, EABI5 version 1 (SYSV) [...]</span></span></code></pre></div><h3 id="庫和可交付結果" tabindex="-1">庫和可交付結果 <a class="header-anchor" href="#庫和可交付結果" aria-label="Permalink to “庫和可交付結果”">​</a></h3><p>這是一個如何使用交叉編譯的簡單的示例。在真實的生活中，你的源文件代碼可能產生的不止於一個二進制文件。雖然你可以手動管理，在這裏手動管理可能不是好的正當理由。在我接下來的文章中，我將説明 GNU 自動工具，GNU 自動工具做了使你的代碼可移植的大部分工作。</p><hr>`,19)),a("p",null,[s[15]||(s[15]=n("via: ",-1)),l(i,{href:"https://opensource.com/article/19/7/cross-compiling-gcc"},{default:p(()=>[...s[14]||(s[14]=[n("https://opensource.com/article/19/7/cross-compiling-gcc",-1)])]),_:1})]),a("p",null,[s[20]||(s[20]=n("作者：",-1)),l(i,{href:"https://opensource.com/users/seth"},{default:p(()=>[...s[16]||(s[16]=[n("Seth Kenlon",-1)])]),_:1}),s[21]||(s[21]=n(" 選題：",-1)),l(i,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[17]||(s[17]=[n("lujun9972",-1)])]),_:1}),s[22]||(s[22]=n(" 譯者：",-1)),l(i,{href:"https://github.com/robsean"},{default:p(()=>[...s[18]||(s[18]=[n("robsean",-1)])]),_:1}),s[23]||(s[23]=n(" 校對：",-1)),l(i,{href:"https://github.com/wxy"},{default:p(()=>[...s[19]||(s[19]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[26]||(s[26]=n("本文由 ",-1)),l(i,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[24]||(s[24]=[n("LCTT",-1)])]),_:1}),s[27]||(s[27]=n(" 原創編譯，",-1)),l(i,{href:"https://linux.cn/"},{default:p(()=>[...s[25]||(s[25]=[n("Linux中國",-1)])]),_:1}),s[28]||(s[28]=n(" 榮譽推出",-1))])])}const y=t(r,[["render",u]]);export{x as __pageData,y as default};
